// SIM_TUNED: a new geometric look requires >=100ms without a qualified
  // range/beam return. This is a re-arm cadence, not a 60Hz Bernoulli trial.
  const FUZE_OPPORTUNITY_REARM_GAP_S_A = 0.100;

